-- Creación de tabla y simulación de datos
CREATE TABLE transacciones (
    id SERIAL PRIMARY KEY,
    usuario_id INT NOT NULL,
    monto NUMERIC(10, 2) NOT NULL,
    fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Consulta antes de crear el índice
EXPLAIN SELECT * FROM transacciones WHERE usuario_id = 105;

-- Creación del índice B-Tree
CREATE INDEX idx_transacciones_usuario ON transacciones(usuario_id);

-- Consulta optimizada
EXPLAIN SELECT * FROM transacciones WHERE usuario_id = 105;
